CREATE TABLE IF NOT EXISTS settlement_jobs (id TEXT PRIMARY KEY, series_id TEXT NOT NULL, expiry_ledger INTEGER NOT NULL, state TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, claimed_by TEXT, claimed_until INTEGER, tx_hash TEXT, error TEXT, updated_at INTEGER NOT NULL, UNIQUE(series_id, expiry_ledger));
CREATE TABLE IF NOT EXISTS reconciliation_drifts (id TEXT PRIMARY KEY, ledger INTEGER NOT NULL, kind TEXT NOT NULL, item_key TEXT NOT NULL, expected TEXT, actual TEXT, replay_from_ledger INTEGER NOT NULL, replay_to_ledger INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_reconciliation_drifts_status ON reconciliation_drifts(status, ledger);
CREATE TABLE IF NOT EXISTS vault_intents (id TEXT PRIMARY KEY, wallet TEXT NOT NULL, asset TEXT NOT NULL, amount TEXT NOT NULL, kind TEXT NOT NULL, nonce TEXT NOT NULL UNIQUE, expires_at INTEGER NOT NULL, confirmed_ledger INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS margin_snapshots (id TEXT PRIMARY KEY, wallet TEXT NOT NULL, ledger INTEGER NOT NULL, snapshot_hash TEXT NOT NULL, initial_margin TEXT NOT NULL, maintenance_margin TEXT NOT NULL, scenario_index INTEGER NOT NULL, created_at INTEGER NOT NULL);
